// Reproducible synthetic reservoir dispatch specification, not an execution framework.
// Each domain record supplies different semantics and concrete operational examples.
import { mkdirSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
const root = dirname(fileURLToPath(import.meta.url));
const records = [
['S1','Intake identity','accept an intake record only when its station identifier is registered and its event identifier has not been used with different content','Station',
 'River telemetry arrives over intermittent radio links. A station may resend an event after losing an acknowledgement, but retransmission is not permission to overwrite a previous observation. Operators need the original event to remain attributable to the physical gauge even when a replacement modem adopts the same network address. Registration belongs to the station rather than the connection. The body includes level, observation time and sensor serial number, so equality of identifiers alone cannot establish equality of observations.',
 [['registered Alder, event a1, level 12','accepted once with original body'],['registered Alder, same a1 and level 12','same acknowledgement, no second record'],['registered Alder, same a1 but level 13','conflict with original record retained'],['unknown Quarry, new event q1','rejected without creating a station']]],
['impl:S1','Observation chronology','reject an observation more than 120 seconds ahead of the receiving clock and retain late observations without moving the latest pointer backward','Instant',
 'Field clocks drift after battery replacement. A future value can otherwise hide several minutes of valid readings and make a falling reservoir appear steady. Late delivery is common after radio outages and remains useful for historical reconstruction. The archive and latest pointer therefore answer different questions: what did the gauge report, and what is the newest admissible observation? Reordering the archive for storage convenience cannot change the event time carried in an observation. Equal timestamps use the event identifier as the deterministic tie breaker.',
 [['receive 10:00:00, observe 10:02:00','accepted at the inclusive future boundary'],['receive 10:00:00, observe 10:02:01','rejected as future clock error'],['latest 09:59, late observation 09:50','archived without pointer regression'],['two valid observations at 09:59','latest chosen by lexical event identifier']]],
['W03','Level units','convert registered centimetre and millimetre readings to integer millimetres before comparisons and reject unknown unit labels','Level',
 'Historical stations encode centimetres while newer probes emit millimetres. Dispatch rules operate on one normalized scale; a unit mismatch can release ten times the intended volume. The original numeric reading and original unit remain available for audit, alongside the normalized value. Conversion does not silently repair a station configuration error. Decimal centimetres are acceptable only when their exact conversion is an integer millimetre. Temperature compensation is upstream of this interface and is not estimated by the dispatch service.',
 [['125 centimetres','normalized to 1250 millimetres'],['1250 millimetres','normalized to 1250 millimetres'],['12.3 centimetres','normalized to 123 millimetres'],['125 metres or unit omitted','rejected with unknown unit reason']]],
['W04','Quality flags','exclude suspect and invalid observations from automatic dispatch while retaining them in the historical archive','Quality',
 'Maintenance crews deliberately immerse sensors during calibration. Such readings are not operational instructions, even if the reported level appears urgent. Quality is assigned at intake from an authenticated station flag and cannot be inferred from the magnitude alone. An operator looking at the archive still needs to see excluded observations to explain why automation paused. A good reading that follows a suspect one restores eligibility only for that new observation; it does not retrospectively bless the suspect measurement or rewrite a past dispatch decision.',
 [['good observation above release level','eligible for subsequent dispatch rules'],['suspect observation above release level','archived but excluded from automation'],['invalid observation below reserve level','archived but excluded from automation'],['good observation following suspect event','only new observation becomes eligible']]],
['W05','Freshness window','pause automatic dispatch when the newest eligible observation is older than 300 seconds at evaluation time','Instant',
 'A frozen radio stream may look like a stable reservoir. The controller checks age on every evaluation rather than relying on the intake service to announce staleness. Age is computed from observation time after the chronology checks, not from the last packet receipt. A retransmitted old reading cannot refresh the clock. Manual operation remains a separate explicitly authorized path; this pause does not manufacture a release order, cancel a physically completed release, or imply that the water itself is safe.',
 [['age 299 seconds','automatic evaluation remains eligible'],['age 300 seconds','automatic evaluation remains eligible'],['age 301 seconds','automatic dispatch pauses with stale reason'],['new receipt of observation aged 900 seconds','pause remains until a fresh observation']]],
['W06','Reserve floor','reject any release whose projected remaining storage would fall below the configured reserve floor','Volume',
 'The reserve protects drinking supply during dry periods. Projection uses normalized current storage minus all committed outstanding releases, not just the order currently being evaluated. Pending requests are not commitments until admitted by the serialized admission operation. Equality with the floor is allowed because the floor itself is a usable engineering boundary, not an exclusive exclusion zone. The response explains which reserve configuration revision was applied so operators can distinguish a real capacity shortage from a configuration rollout.',
 [['storage 1000, outstanding 100, floor 700, request 200','accepted with projected remainder 700'],['same storage and commitments, request 201','rejected below floor'],['storage 1000, floor 1100, request zero','rejected because reserve already violated'],['storage 1000, two concurrent requests 200 and 201','only a serially admissible set is committed']]],
['W07','Release ceiling','reject a requested release volume greater than the station configured per-order ceiling without splitting it into smaller orders','Volume',
 'The ceiling limits the physical exposure of one command. Automatically subdividing a rejected order would defeat that control and obscure the human intent behind the request. Several independent authorized orders may still exist, subject to reserve and concurrency rules, but the service does not synthesize those orders on behalf of an over-limit caller. Each response includes the ceiling used, and a rejection does not allocate a physical command sequence number. Zero volume is handled by the command validity rule rather than by this upper-bound rule.',
 [['ceiling 500, requested volume 499','eligible under ceiling'],['ceiling 500, requested volume 500','eligible at boundary'],['ceiling 500, requested volume 501','rejected as one over-limit request'],['ceiling changed after rejection, retry unchanged request','re-evaluated under recorded new revision']]],
['W08','Command volume validity','accept command volume only as a positive safe integer number of litres and reject coercible strings, fractions and nonfinite numbers','Volume',
 'A physical release cannot be meaningfully represented by a negative volume or by an imprecise floating point integer. The public API uses litres to avoid hidden unit choices. Clients that store quantities as text convert them explicitly before submitting commands; the server does not accept a string merely because JavaScript could parse it. This boundary protects both hydraulic calculations and accounting totals. Rejection is a typed validation result, not a successful zero-volume release and not a low-level arithmetic exception.',
 [['numeric volume 1 litre','accepted by volume validator'],['numeric volume 0 litres','rejected as nonpositive'],['string 10 or number 1.5','rejected without coercion or rounding'],['Infinity, NaN, or unsafe integer','rejected as unrepresentable volume']]],
['W09','Lease ownership','allow command admission only to the current unexpired dispatch lease holder for that station','Lease',
 'Two regional controllers can observe the same telemetry, but only one can issue automatic releases. The lease prevents both controllers from treating a network partition as permission to act. Ownership is checked inside the same admission operation that records the order. A cached lease read from an earlier request is insufficient. An expired holder may still query history and report a completed physical action, but it cannot admit a new action using a familiar owner name or an old fencing token.',
 [['current owner north, lease valid, north submits','eligible for admission'],['current owner north, south submits','rejected as nonowner'],['owner north submits at expiry instant','rejected as expired'],['north retries using superseded fencing token','rejected despite matching owner name']]],
['W10','Fencing sequence','increase the station fencing token on every lease grant and reject actuator acknowledgements carrying an older token','Lease',
 'A delayed controller can resume after a pause with commands already queued in memory. Monotonic fencing allows the actuator and ledger to recognize that those commands belong to an obsolete authority period. Tokens are scoped to a station and are not compared across unrelated reservoirs. Restarting the service does not reset the sequence. Acknowledgements with an unknown future token indicate a configuration or protocol error and remain unresolved rather than promoting themselves into current authority.',
 [['grant after token 41','new token greater than 41'],['acknowledgement token 41 while current is 42','rejected as fenced'],['acknowledgement token 42 for matching order','eligible for completion checks'],['restart after token 42, next grant','token continues above persisted 42']]],
['W11','Idempotent orders','return the original order result for a repeated idempotency key with identical normalized content and reject changed content under that key','Order',
 'Clients retry after timeouts because an HTTP failure does not reveal whether an actuator command was admitted. The idempotency key belongs to a station and submitting principal, avoiding accidental collisions between independent customers. Normalized content includes volume, station, reason and requested execution window. The first accepted request fixes these fields for the key. A different textual representation that normalizes to the same content does not create another order, while a real change requires a new key and a fresh admission decision.',
 [['key k1, volume 20 repeated exactly','original order identifier returned'],['key k1 originally 20, retry volume 21','conflict without new physical order'],['same key at different station','independent key namespace'],['timeout after commit followed by retry','single commitment and original result']]],
['W12','Order expiration','refuse to begin an admitted order after its execution window closes and release its unused reservation exactly once','Instant',
 'An admitted release is not permission to operate indefinitely. A late command can collide with maintenance or a downstream warning window. Expiration is evaluated at the actuator start decision and may therefore occur after a successful API admission. The reservation remains visible until the expiration transition is durable. Replayed expiration notifications do not add storage back repeatedly. A command that already started before the deadline follows completion handling rather than being retroactively classified as never executed.',
 [['window closes 12:00, start at 11:59:59','start remains eligible'],['window closes 12:00, start at 12:00','refused as expired'],['same expiration event delivered twice','reservation released once'],['started 11:59, completion 12:01','completed through started-order path']]],
['W13','Cancellation race','cancel only an admitted order that has not started and serialize cancellation against the start transition','Order',
 'Operators can withdraw an intention before machinery begins moving. They cannot safely erase a physical action merely because a cancellation packet reaches the server first on another connection. The authoritative transition is recorded in the order ledger. If start wins the race, cancellation reports that execution has begun; if cancellation wins, later start attempts fail. Neither outcome silently reports both success states. Accounting follows the winning durable transition and retains the losing request as an audit event.',
 [['cancel admitted unstarted order','cancelled and reservation released'],['cancel already started order','refused with started status'],['start and cancel concurrently','one transition wins, never both'],['repeat successful cancellation','same cancelled status, no second release']]],
['W14','Completion evidence','mark an order completed only after a matching authenticated actuator receipt records actual released litres','Receipt',
 'An API acknowledgement says that an order entered the ledger, not that water moved. Physical completion arrives on a separate authenticated channel and may report less than the requested volume. The record distinguishes requested, reserved and actual quantities. An absent receipt leaves the outcome uncertain; time passing alone cannot manufacture completion. A malformed receipt remains visible as an operational error without corrupting the accepted order. Operators may investigate uncertainty, but reconciliation never substitutes a guessed volume for actuator evidence.',
 [['matching authenticated receipt for 18 of requested 20','completed with actual 18 recorded'],['HTTP admission succeeded without actuator receipt','not completed'],['receipt references another order','rejected without altering target order'],['unauthenticated receipt claims full release','rejected and security event recorded']]],
['W15','Duplicate receipts','apply a matching completion receipt once and flag differing receipts for the same order as reconciliation conflicts','Receipt',
 'Actuator radios resend receipts until they receive acknowledgement. The service needs idempotent completion without hiding contradictory physical evidence. Equality includes actuator identity, fencing token, actual volume and completion timestamp. A duplicate preserves the first acknowledgement. A conflicting later receipt does not overwrite the first one or silently average their quantities; it opens an explicit reconciliation condition. Storage projections use the durable accepted quantity while the conflict remains visible to an operator.',
 [['same receipt delivered three times','one completion accounting effect'],['same order later reports different actual volume','reconciliation conflict raised'],['same volume but different actuator identity','conflict rather than silent duplicate'],['acknowledgement lost and exact receipt retried','original acknowledgement returned']]],
['W16','Maintenance lock','reject automatic admission while a station maintenance lock is active and require an explicit authorized unlock','Lock',
 'Maintenance technicians work near moving equipment. A controller restart, lease renewal or fresh telemetry packet does not imply that personnel have left the site. Locks therefore survive ordinary service lifecycle events and remain separate from transient communication alarms. The lock includes operator identity and a reason, giving the control room a contact point. Manual emergency procedures are outside automatic dispatch and cannot be invoked by merely labeling a normal request urgent. Removing the lock is itself an auditable privileged operation.',
 [['active maintenance lock with otherwise valid order','automatic admission rejected'],['restart while maintenance lock active','lock remains active'],['lease renewed under lock','no implicit unlock'],['authorized explicit unlock with reason','future admissions may proceed']]],
['W17','Operator authorization','require the dispatch role for manual release and the maintenance role for lock changes, checking roles at request time','Principal',
 'The identity provider can revoke access during a shift. A long-lived browser session is not proof that the operator still has the role needed for a dangerous action. Roles are purpose-specific: maintaining equipment does not automatically authorize water release, and dispatch authority does not permit clearing a technician safety lock. Read-only observers can inspect history without acquiring either privilege. Authentication failures and authorization denials remain distinguishable in audit records without exposing bearer credentials.',
 [['dispatch role requests manual release','authorized for subsequent safety checks'],['observer role requests manual release','denied without reservation'],['dispatch-only role requests unlock','denied for missing maintenance role'],['role revoked after login before request','request denied using current roles']]],
['W18','Audit attribution','record principal, station, source event, configuration revision and decision reason for every admitted or rejected command','Audit',
 'An incident reconstruction needs to explain why the controller acted, not only what command it produced. Rejected attempts also matter because repeated reserve failures can reveal a broken client or malicious operator. Attribution links the decision to the telemetry and configuration actually used, even if those inputs later change. Sensitive credentials are never the identity field. The audit record is written with the decision so a successful response cannot exist without a corresponding explanation of the authority and state consulted.',
 [['admitted automatic order','audit links owner, source event and revision'],['rejected reserve-floor order','audit records reserve reason and revision'],['manual request with bearer credential','principal recorded, credential excluded'],['configuration changes immediately after decision','audit retains decision-time revision']]],
['W19','Audit integrity','append audit entries without modifying previous entries and reject an administrative request to rewrite decision history','Audit',
 'Corrections sometimes follow a calibration investigation, but they are new facts with their own author and timestamp. Replacing a past record would make earlier decisions appear to have used information that was unavailable at the time. The audit stream therefore permits explanatory correction entries linked to their targets, not in-place edits. Export ordering uses a durable sequence independent of wall-clock skew. Storage maintenance may change physical layout while preserving the logical content and integrity sequence visible to auditors.',
 [['operator corrects station annotation','new linked correction entry appended'],['administrator requests overwrite of original reason','request rejected'],['two entries share wall-clock timestamp','durable sequence determines order'],['storage compaction completes','logical entries and integrity links unchanged']]],
['W20','Configuration revision','activate a complete validated configuration atomically and keep the previous active revision when validation fails','Revision',
 'Reserve floors, release ceilings and warning thresholds are reviewed together. Exposing half of an update could produce a combination that no engineer approved. Draft edits are not active configuration. Validation checks structural types and cross-field relationships before the activation boundary. Every command sees one whole revision, and rollback is an explicit activation of a known validated revision rather than a collection of ad hoc field writes. An unsuccessful activation leaves dispatch behavior tied to the previous revision.',
 [['valid complete revision r8 replaces r7','all subsequent decisions see r8'],['r8 has floor greater than reservoir capacity','activation rejected, r7 remains'],['request races activation','uses either whole r7 or whole r8'],['rollback to validated r6','new activation event identifies r6']]],
['W21','Threshold hysteresis','enter high-water alert at or above the high threshold and clear it only below the separate lower reset threshold','Level',
 'A noisy probe can alternate around a single threshold many times per minute. Hysteresis prevents that measurement noise from repeatedly paging the same operator. The alert state is remembered across evaluations and across process restarts. Configuration validation requires the reset threshold to be strictly below the high threshold. Alert state does not itself authorize a release; dispatch still applies freshness, quality, reserve and lease checks. Clearing the alert produces its own event so subscribers can reconcile their displays.',
 [['high 1500, reset 1400, rising level 1500','alert enters active state'],['active alert at level 1400','alert remains active'],['active alert at level 1399','alert clears'],['reset threshold equals high threshold','configuration rejected']]],
['W22','Downstream warning','delay release start until the configured downstream warning interval has elapsed after durable warning publication','Instant',
 'Communities downstream need time to move away from the channel. Generating a message in memory is not evidence that the warning was published. The order records the durable publication timestamp used to establish the waiting interval. Reissuing the same warning after an acknowledgement loss does not shorten the wait. If publication is unavailable, the order remains unstarted and may eventually expire through the normal window rule. A manual override is not implied by operator impatience or by a high reservoir reading.',
 [['warning interval 60 seconds, elapsed 59','start delayed'],['warning interval 60 seconds, elapsed 60','start eligible'],['warning generation succeeded but publication failed','start remains delayed'],['warning retry with same publication identity','original durable timestamp retained']]],
['W23','Warning delivery targets','publish warnings to every configured required downstream destination before treating publication as complete','Destination',
 'A region may have several independently operated sirens and public notification gateways. Delivery to the first healthy endpoint cannot stand in for delivery to all required destinations. Optional destinations can fail without blocking publication completion, but their failures remain observable. The required destination set is captured from the order configuration revision, so a concurrent edit cannot quietly remove an inconvenient recipient. Retrying a failed destination preserves the same warning identity and avoids duplicate public incidents.',
 [['two required destinations both acknowledge','publication complete'],['one required succeeds and one fails','publication incomplete'],['all required succeed, optional destination fails','complete with optional delivery warning'],['destination list edited during retries','captured required set still governs order']]],
['W24','Retry budget','stop automatic actuator delivery after three failed attempts and expose the order as delivery-uncertain without claiming physical failure','Order',
 'A timeout is ambiguous: the actuator may have executed the command and lost its reply. Unlimited retries can congest radio links during an incident, while declaring definite failure invites unsafe duplicate manual action. The delivery budget bounds attempts for one order identity. Attempts retain the same idempotency and fencing information. Operators see the uncertainty and can reconcile against physical receipts. A late authenticated receipt can still resolve an uncertain order through the normal completion rules.',
 [['first delivery times out','retry permitted with same order identity'],['third failed delivery completes','automatic attempts stop'],['budget exhausted without physical receipt','status delivery-uncertain, not confirmed failed'],['late matching receipt arrives after exhaustion','normal receipt reconciliation applies']]],
['W25','Retry scheduling','space automatic retries by at least ten seconds using a monotonic clock and never busy-loop on transport failure','Duration',
 'During a radio outage, rapid retries consume the limited channel capacity needed for emergency messages. A monotonic interval avoids clock synchronization adjustments making the controller think time has moved backward or forward. The retry schedule is subordinate to the execution window: a scheduled attempt outside that window is not sent merely because it was previously queued. Restart recovery retains enough timing information to avoid an immediate burst of all pending attempts. The service exposes the next eligible attempt time to operators.',
 [['failure followed by nine elapsed seconds','no second attempt yet'],['failure followed by ten elapsed seconds','next attempt eligible if window open'],['wall clock jumps forward during wait','monotonic spacing still enforced'],['next eligible retry after execution window','expire rather than send']]],
['W26','Queue fairness','select the oldest eligible order within each station priority class and prevent a blocked order from starving eligible orders in other stations','Order',
 'Regional dispatch shares a bounded transport worker pool. One station can remain blocked by maintenance or warning delivery while another is ready to operate safely. Fairness concerns eligible work rather than raw queue position. Within a station priority class, admission sequence provides stable ordering when timestamps tie. The scheduler cannot use fairness as a reason to bypass station safety checks or change a caller priority. Queue inspection reports why an earlier item was skipped so operators do not mistake eligibility filtering for lost orders.',
 [['two eligible same-priority orders at one station','earlier admission selected first'],['oldest order blocked at Alder, Birch ready','Birch receives service'],['equal timestamps within same priority class','admission sequence breaks tie'],['high priority order under maintenance lock','remains ineligible despite priority']]],
['W27','Admission concurrency','admit at most one executing release per station and serialize reserve accounting across concurrent requests','Order',
 'Two valid requests evaluated against the same storage snapshot can jointly violate the reserve floor. The service therefore makes admission and reservation a single serializable operation for each station. Regional concurrency is still possible because independent stations have independent physical equipment and storage. The executing-release restriction includes orders whose physical start is recorded but whose completion receipt is outstanding. Uncertainty does not free the station for another release simply because a client stopped waiting for the first result.',
 [['two requests each individually fit but jointly exceed reserve','only admissible serialized subset accepted'],['one executing release and another start request','second start refused or waits'],['independent ready orders at Alder and Birch','both may execute concurrently'],['first order started but receipt missing','station execution slot remains occupied']]],
['W28','Recovery replay','reconstruct reservations and order states from durable records after restart without reissuing completed or cancelled orders','Revision',
 'The in-memory queue is a convenience, not the authoritative history. Recovery rebuilds it from durable state transitions and treats replay as reconstruction rather than a fresh request stream. Completion and cancellation have accounting effects exactly once across any number of restarts. An order whose transport outcome is uncertain remains uncertain until evidence resolves it. The startup process exposes readiness only after reconstruction has established the station reservations and execution slots needed for safe admission.',
 [['restart after completion recorded','completed order not sent again'],['restart after cancellation recorded','reservation remains released exactly once'],['restart with admitted unstarted order','reservation restored and eligibility rechecked'],['restart with uncertain started order','uncertainty and occupied slot preserved']]],
['W29','Read consistency','return order status and its accounting revision from one consistent snapshot and identify stale replicated reads explicitly','Revision',
 'An operator may query a regional replica while the authoritative station controller is recording a receipt. Showing completed status with an old reserved volume would create a contradictory screen that appears to lose water. A response therefore names the revision represented by both fields. Replicas may serve history during an outage if they disclose staleness rather than pretending to be current authority. Admission never relies on a stale public read response as a substitute for its serialized authoritative state.',
 [['completion and reservation update commit together','read shows both from same revision'],['replica lags primary by two revisions','response marks replicated staleness'],['client supplies earlier read revision to admission','server rechecks authoritative state'],['status unavailable at requested revision','explicit unavailable result, not mixed fields']]],
['W30','Export pagination','produce stable audit export pages using a snapshot boundary and an opaque continuation token without skipping or duplicating entries','Audit',
 'Large incident exports span many requests while new decisions continue to arrive. Offset pagination over a changing stream can repeat entries or move them between pages. The first request fixes an upper audit sequence for the export, and later pages retain that boundary. Tokens are scoped to the requesting principal and export filter. A malformed or expired token is a visible error rather than a request for the first page, because silent restart would corrupt a downstream reconstruction.',
 [['new audit events arrive between export pages','excluded beyond original snapshot boundary'],['valid continuation after first page','next entries without duplicates'],['token reused with different station filter','rejected as incompatible token'],['malformed or expired token supplied','explicit token error rather than empty success']]],
['W31','Retention cutoff','retain operational audit entries for at least 400 days and suspend deletion for stations under an active legal hold','Duration',
 'Routine storage cleanup operates independently from control dispatch. Retention is measured from durable entry time rather than a possibly inaccurate field observation clock. Legal hold covers linked correction entries and receipts as well as admission decisions, preserving a coherent incident record. Removing a hold resumes normal eligibility checks but does not force immediate deletion. A failed cleanup job is observable and does not impair command safety by treating audit storage exhaustion as permission to stop recording decisions.',
 [['entry age 399 days without hold','retained'],['entry age exactly 400 days without hold','eligible under minimum retention boundary'],['entry age 500 days with active hold','retained despite age'],['hold removed from old station records','normal cleanup eligibility resumes']]],
['W32','Secret redaction','exclude credentials and raw authorization headers from logs, audit exports and user-visible error details','Principal',
 'A useful operational trace can identify the actor without carrying the token that allowed the actor to authenticate. Redaction applies on success paths and error paths, including malformed requests that trigger validation before a normal principal object exists. Station serial numbers are operational identifiers, not authentication material, and remain available where appropriate. A diagnostic request for verbose logging does not waive this boundary. Tests use synthetic secret markers so accidental disclosure is detectable without introducing actual credentials into the fixture.',
 [['valid request carries synthetic bearer marker','marker absent from logs and exports'],['malformed authorization header triggers error','raw header absent from error detail'],['operator requests verbose incident export','credentials still excluded'],['audit entry names authenticated principal','stable principal identifier remains available']]],
['W33','Rate isolation','limit each submitting principal to 30 admission attempts per rolling minute without charging read-only queries against that budget','Principal',
 'A misconfigured client should not monopolize the admission service or prevent operators from inspecting an incident. Attempts count whether admission succeeds or fails safety validation, because both consume serialized work. Authentication failures without a known principal use a separate protective mechanism outside this fixture; they do not charge an arbitrary victim account. The response provides a retry delay when the admission budget is exhausted. Administrative privilege does not silently bypass the budget unless a separate approved policy explicitly changes it.',
 [['principal makes thirtieth attempt inside minute','attempt admitted to normal validation'],['same principal makes thirty-first attempt','rate-limited before admission work'],['principal queries history after thirty attempts','read remains available'],['another principal submits during first principal limit','independent budget applies']]],
['W34','Health semantics','report not-ready when durable storage or reservation reconstruction is unavailable while keeping liveness independent of downstream warning delivery','Quality',
 'Load balancers need to know whether an instance can safely admit commands, not merely whether its process responds. An instance that cannot persist decisions is not ready for admission. Conversely, a failed downstream warning endpoint does not mean that the whole process is dead; restarting it repeatedly would lose diagnostic continuity and create unnecessary reconnection load. Health responses carry concise reason codes without exposing credentials or internal connection strings. Recovery transitions become visible only after the required readiness condition actually succeeds.',
 [['durable storage unavailable','readiness false with storage reason'],['reservation reconstruction still running','readiness false until complete'],['downstream warning destination unavailable','liveness remains true, delivery alarm visible'],['process event loop healthy but admission unsafe','live and not-ready are distinguishable']]],
['W35','Metric dimensions','publish admitted, rejected and uncertain order counters by station and reason without using order identifiers as metric labels','Audit',
 'Metrics support regional operations without creating one time series for every command. High-cardinality order identifiers belong in searchable event records, not label sets. Counter increments correspond to durable transitions so retries and duplicate receipts do not inflate physical activity reports. A rejection reason remains a bounded code rather than a free-form client string. Operators can link from a metric interval to audit records for details, preserving the distinction between aggregate observation and authoritative per-order evidence.',
 [['duplicate idempotent admission request','no second admitted transition increment'],['reserve rejection recorded','rejected counter increments with reserve code'],['delivery budget exhausted','uncertain transition increments once'],['order has unique external identifier','identifier absent from metric label keys']]],
['W36','Simulation isolation','run preview calculations without allocating order identifiers, reservations, actuator messages or durable admission audit entries','Order',
 'Engineers preview a release to understand its projected effect before asking for approval. A preview is not a partially admitted command and cannot consume scarce station capacity. The response includes the configuration and observation revisions used so the user knows that later admission may see changed inputs. Preview access itself may be logged as an access event, clearly separate from a command decision. A successful preview does not guarantee future admission and is never presented as measured physical release evidence.',
 [['preview valid proposed release','projection returned without reservation'],['preview would violate reserve','predicted rejection without actual order'],['actual admission follows earlier preview','all checks rerun against current state'],['preview endpoint called repeatedly','no actuator message or order sequence allocation']]],
['W37','Emergency preference boundary','treat a caller urgency label as scheduling preference only and never bypass reserve, maintenance, lease or warning constraints','Order',
 'Operators naturally mark requests urgent during storms. That label can influence ordering among otherwise eligible work, but it is not a universal override authority. Physical constraints and personnel safety remain binding. A genuinely different emergency operating policy requires a separately approved configuration or manual procedure with its own provenance. The normal API records the requested urgency and the checks it applied, allowing later review to distinguish an urgent rejected request from a silently relaxed safety rule.',
 [['urgent request below reserve floor','rejected despite urgency'],['urgent request under maintenance lock','rejected despite scheduling preference'],['urgent eligible request beside ordinary eligible work','priority may affect scheduling'],['caller writes override in free-text reason','no new authority inferred from text']]],
['W38','Cross-region failover','grant replacement regional dispatch authority only after the previous lease expires or is durably revoked with a higher fencing token','Lease',
 'A regional outage does not reveal whether the old controller has lost contact with every actuator. Failover waits for an authoritative ownership transition rather than treating failed health probes as proof of exclusive access. The replacement controller reconstructs station reservations before it admits work. Existing orders retain their identities through the move, and receipts from the old region are evaluated by order and fencing rules rather than discarded simply because the network origin changed. Availability is important, but it does not redefine ownership.',
 [['old region unreachable but lease unexpired','replacement does not admit commands'],['old lease expired, new grant token advanced','replacement may proceed after reconstruction'],['durable revocation recorded with higher token','old token fenced immediately'],['late old-region receipt for valid completed order','evaluated under receipt and fencing rules']]],
['W39','Schema evolution','read the previous persisted order schema during rolling upgrade and reject unknown future schema versions without deleting their records','Revision',
 'Regional nodes are upgraded in stages, so the storage layer can temporarily contain records written by two supported versions. Compatibility conversion preserves original identifiers, quantities and decision provenance. A node that encounters a future format it cannot interpret reports an explicit compatibility error and avoids destructive cleanup. The migration is not allowed to convert unknown data into an empty order list, because that would free reservations and permit unsafe duplicate work. Qualification exercises restart and mixed-version reads, not merely fresh installation.',
 [['current node reads previous supported schema','order semantics preserved'],['older node encounters unknown future schema','explicit incompatibility without deletion'],['migration processes existing reservation','quantity and identity unchanged'],['rolling upgrade restarts while migration incomplete','no false empty-state readiness']]],
['W40','Tail reconciliation','reconcile actual released volume against reservations at the end of an incident and report unresolved receipts separately from measured totals','Receipt',
 'The incident closeout is the last place where a plausible guess can become an apparently authoritative number. Requested volume, reserved volume and measured released volume answer different questions and remain separate totals. An unresolved order is listed with its identity and missing evidence rather than assigned its requested volume as an estimate. Closeout can be produced with explicit uncertainty, but it cannot claim complete measured reconciliation until every included order has adequate receipt evidence. This tail requirement intentionally appears after the normal first-read truncation boundary.',
 [['requested 100, authenticated actual receipt 80','measured total increases by 80 only'],['requested 100 with no completion receipt','unresolved list includes order, measured total unchanged'],['duplicate receipt included in incident range','actual volume counted once'],['all receipts reconciled but qualification unrun','measurement totals do not imply gate passed']]],
];
const defs = `# Reservoir definitions\n\n${[
['Station','A registered physical reservoir and its gauge/actuator identity; a network address is not an identity.'],
['Instant','UTC observation or event time with second precision; an execution window is closed at its end instant.'],
['Level','An exact integer millimetre distance above the registered station datum.'],
['Quality','One of good, suspect, invalid; only good observations are eligible for automatic dispatch.'],
['Volume','A positive JavaScript safe integer number of litres for command input; accounting may also represent zero.'],
['Lease','Station-scoped exclusive dispatch ownership with an expiry and monotonically increasing fencing token.'],
['Order','A durable release intention with immutable identity, normalized content, lifecycle state and reservation.'],
['Receipt','Authenticated actuator evidence carrying order, actual litres, actuator, token and completion instant.'],
['Lock','A durable maintenance safety state changed only by explicitly authorized maintenance operations.'],
['Principal','An authenticated actor with current purpose-specific roles; never the raw bearer credential.'],
['Audit','Append-only decision and transition history with a durable sequence and source provenance.'],
['Revision','An immutable identity for a complete configuration or consistent durable state snapshot.'],
['Destination','A named downstream publication endpoint classified as required or optional by configuration.'],
['Duration','Elapsed time measured on a monotonic clock for scheduling and durable UTC age for retention.'],
].map(([n,d])=>`## ${n}\n${d}\n`).join('\n')}`;
const lines = ['# Reservoir dispatch service — complete synthetic authority', '',
'This specification governs a regional reservoir dispatch service. It is deliberately longer than a single ordinary tool read. Sections are ordered along the path from field observation through command admission, physical execution, audit and incident closeout. The subject is asked to plan implementation, not to claim that this document describes an already implemented system. Each numbered clause is binding. Unnumbered safety clauses and qualification gates near the end are equally binding. Examples explain the meaning of the corresponding clause; they do not authorize deviations from another section.', '',
'Existing source identifiers S1 and impl:S1 belong to this authority and are not implementation-step names. Preserve them exactly. Definitions in definitions.md apply throughout. Annex acceptance procedures in annex.md are normative for the three gates. Neither a caller summary nor a shorter plan replaces these files. Where an example says eligible, that means eligible under this one rule; all other applicable rules still apply. A recorded planned test is not a measurement, and an illustrative operational sequence below is not a test receipt.', ''];
const oracle=[];
function clause(id,type,text,definition,acceptance) { lines.push(text); oracle.push({id,type,file:'SPEC.md',line:lines.length,clause:text,definition,acceptance}); }
records.forEach(([id,title,rule,def,context,cases],i)=>{
 lines.push(`## ${i+1}. ${title} [${id}]`, '');
 clause(id,'requirement',`${id}: The service MUST ${rule}.`,`definitions.md#${def}`,`Exercise ${cases.map(([input,outcome])=>`${input} => ${outcome}`).join('; ')}. Verify rejection leaves unrelated station state unchanged.`);
 lines.push('',`Normative definition: definitions.md#${def}.`, '',context,'',`Operational interpretation for ${title.toLowerCase()}:`, '');
 cases.forEach(([input,outcome],j)=>{
   lines.push(`### ${id} example ${j+1}`, '',
   `Given ${input}, the expected result is ${outcome}. Inspect the ${def.toLowerCase()} state and response together when evaluating this ${title.toLowerCase()} boundary.`, '');
 });
 // Distinct domain narrative above plus concrete acceptance examples, not byte padding.
});
const locals=[
['Safety isolation','The service SHALL preserve independent station state when rejecting a command for another station.','Station','Submit an invalid Alder request while Birch has a valid reservation; compare Birch state before and after.'],
['Error visibility','The service MUST return a typed detectable error for malformed input rather than a successful empty result.','Quality','Submit missing station and malformed volume; verify checked validation errors and no success-shaped empty order.'],
['Authority provenance','The service SHALL retain the source configuration revision used for every safety decision even after later configuration activation.','Revision','Activate a new floor after a rejection; inspect the old audit record and verify its original revision remains.'],
['Evidence separation','The service MUST distinguish requested, reserved and physically measured volume in every incident summary.','Receipt','Mix completed, pending and uncertain orders; verify three distinct totals and the unresolved list.'],
['No implicit override','The service SHALL require explicit approved policy provenance before applying any deviation from these safety constraints.','Principal','Submit a caller preference to skip warnings; verify no bypass occurs without a separately approved policy.'],
['Clock uncertainty','The service MUST surface unavailable time synchronization as an uncertainty instead of inventing a current observation timestamp.','Instant','Disable clock evidence in a replay; inspect uncertainty and confirm no fabricated freshness qualification.'],
['Export confidentiality','The service SHALL apply the same secret redaction to incident exports as to live operational logs.','Audit','Export malformed authentication attempts containing a synthetic token; inspect every output field for disclosure.'],
['Closeout completeness','The service MUST include unresolved safety and evidence gaps in an incident closeout even when every available unit test is green.','Receipt','Run happy-path tests with one receipt absent; verify closeout retains the missing-receipt gap and does not claim complete coverage.'],
];
locals.forEach(([title,rule,def,acceptance],i)=>{lines.push(`## Safety note: ${title}`, ''); clause(`local:SPEC:safety:${i+1}`,'local',rule,`definitions.md#${def}`,acceptance); lines.push('',`Acceptance procedure: ${acceptance} This clause is not assigned a numbered source requirement ID. Its map entry uses a stable source/section/ordinal locator and retains the clause itself. The locator identifies existing authority; it does not create a new policy or reduce the meaning to a keyword. Qualification examines the observable boundary described here, including the failure path, alongside the numbered requirements that use the same underlying state.`, '');});
for (const [id,title,rule,acceptance] of [
 ['QUAL-1','Boundary qualification','execute all numbered and unnumbered boundary acceptance cases on the final candidate','Retain command, exit status, complete output and candidate source/test hashes for all 48 obligation rows.'],
 ['QUAL-2','Recovery qualification','execute restart, duplicate-message and concurrent-admission probes with durable state preserved','Demonstrate restart after commit, duplicate completion and racing reserve requests; inspect actual state, not only response strings.'],
 ['QUAL-3','Incident qualification','execute the annex incident replay and show unresolved evidence remains explicit in closeout','Inspect mixed measured and missing receipts, tail W40 and all safety notes; retain final artifacts and actual measurements.'],
]) {lines.push(`## ${title}`, '');clause(id,'gate',`${id} (Gate): Qualification SHALL ${rule}.`,'annex.md#Qualification',acceptance);lines.push('',acceptance,'');}
mkdirSync(join(root,'fixtures/long-spec'),{recursive:true}); mkdirSync(join(root,'oracles'),{recursive:true});
writeFileSync(join(root,'fixtures/long-spec/SPEC.md'),lines.join('\n')+'\n');
writeFileSync(join(root,'fixtures/long-spec/definitions.md'),defs);
